// Opaque, one-shot handles keep generated bytes out of URLs and persistent storage.
window.WFLocalFiles = (() => {
  const files = new Map();
  const lifetime = 10 * 60 * 1000;
  function discard(id) {
    const entry = files.get(id);
    if (!entry) return;
    clearTimeout(entry.timer);
    files.delete(id);
  }
  // One download for a multi-file set: browsers cannot roll back individual
  // downloads. Store-mode ZIP keeps every original filename and byte intact.
  async function downloadSet(entries, requireCurrent = () => {}) {
    if (entries.length === 1) {
      requireCurrent();
      await WFFileSystem.writeBlob(null, entries[0].name, entries[0].blob);
      return entries[0].name;
    }
    const encoder = new TextEncoder(), bodies = [], directory = [];
    let offset = 0, directorySize = 0;
    const record = size => {
      const bytes = new Uint8Array(size);
      return { bytes, view: new DataView(bytes.buffer) };
    };
    for (const entry of entries) {
      const name = encoder.encode(entry.name), data = new Uint8Array(await entry.blob.arrayBuffer());
      if (name.length > 65535 || data.length > 0xffffffff || offset + data.length + name.length + 30 > 0xffffffff) {
        throw new Error('This output set is too large to download together. Choose a writable folder.');
      }
      let crc = 0xffffffff;
      for (const byte of data) {
        crc ^= byte;
        for (let bit = 0; bit < 8; bit++) crc = (crc >>> 1) ^ ((crc & 1) ? 0xedb88320 : 0);
      }
      crc = (crc ^ 0xffffffff) >>> 0;
      const local = record(30), central = record(46);
      local.view.setUint32(0, 0x04034b50, true);
      local.view.setUint16(4, 20, true);
      local.view.setUint16(6, 0x800, true); // UTF-8 filenames
      local.view.setUint16(12, 33, true); // 1980-01-01
      local.view.setUint32(14, crc, true);
      local.view.setUint32(18, data.length, true);
      local.view.setUint32(22, data.length, true);
      local.view.setUint16(26, name.length, true);
      central.view.setUint32(0, 0x02014b50, true);
      central.view.setUint16(4, 20, true);
      central.bytes.set(local.bytes.subarray(4, 28), 6);
      central.view.setUint32(42, offset, true);
      bodies.push(local.bytes, name, data);
      directory.push(central.bytes, name);
      offset += 30 + name.length + data.length;
      directorySize += 46 + name.length;
    }
    if (entries.length > 65535 || offset + directorySize > 0xffffffff) throw new Error('Choose a writable folder for this output set.');
    const end = record(22);
    end.view.setUint32(0, 0x06054b50, true);
    end.view.setUint16(8, entries.length, true);
    end.view.setUint16(10, entries.length, true);
    end.view.setUint32(12, directorySize, true);
    end.view.setUint32(16, offset, true);
    const name = 'Wavefinity files.zip';
    requireCurrent();
    await WFFileSystem.writeBlob(null, name, new Blob([...bodies, ...directory, end.bytes], { type: 'application/zip' }));
    return name;
  }
  return {
    put(bytes, type = 'application/octet-stream') {
      const id = crypto.randomUUID();
      const blob = new Blob([bytes], { type });
      files.set(id, { blob, timer: setTimeout(() => discard(id), lifetime) });
      return id;
    },
    claim(id) { const blob = files.get(id)?.blob; discard(id); return blob || null; },
    discard,
    discardAll() { for (const id of files.keys()) discard(id); },
    downloadSet,
  };
})();
